def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    return 1
for p in factors:
    tau *= (factors[p] + 1)

def calculate_F(x):
    # F(x) = (tau(x^2) - 1) / 2
    x_squared = x * x
    factors = prime_factorization(x_squared)
    tau_x2 = 1
    for exponent in factors.values():
        tau_x2 *= (exponent + 1)

    return (tau_x2 - 1) // 2

